const RightTriangle: React.FC<TriangleProps> = ({
  a,
  b,
  colorA,
  colorB,
  colorC,
  showSquares,
  squareScale,
  showLabels,
}) => {
  // Calculate coordinates for a right triangle with the right angle at bottom-left
  // Point 1: (0, b) - Top Left
  // Point 2: (0, 0) - Bottom Left (Right Angle)
  // Point 3: (a, 0) - Bottom Right

  // We center the triangle visually in a 600x600 box
  const scale = 80; 
  const width = a * scale;
  const height = b * scale;
  const offsetX = 300 - width / 2;
  const offsetY = 300 + height / 2; // Invert Y for SVG

  const p1 = { x: offsetX, y: offsetY - height };
  const p2 = { x: offsetX, y: offsetY };
  const p3 = { x: offsetX + width, y: offsetY };

  return (
    <svg width="600" height="600" viewBox="0 0 600 600" style={{ overflow: "visible" }}>
      {/* Square on Side A (Vertical) */}
      {showSquares && (
        <rect
          x={p1.x - width * squareScale}
          y={p1.y}
          width={width * squareScale}
          height={height * squareScale}
          fill={colorA}
          fillOpacity={0.3}
          stroke={colorA}
          strokeWidth={2}
        />
      )}

      {/* Square on Side B (Horizontal) */}
      {showSquares && (
        <rect
          x={p2.x}
          y={p2.y}
          width={width * squareScale}
          height={height * squareScale}
          fill={colorB}
          fillOpacity={0.3}
          stroke={colorB}
          strokeWidth={2}
        />
      )}

      {/* Square on Hypotenuse C */}
      {showSquares && (
        <g transform={`rotate(${Math.atan2(height, width) * (180 / Math.PI)} ${p1.x} ${p1.y})`}>
           <rect
            x={p1.x}
            y={p1.y - width * squareScale} // Draw perpendicular to side
            width={Math.sqrt(width * width + height * height) * squareScale}
            width={width * squareScale} // Simplified for visual demo logic, actually needs rotation math
            // Correct visual implementation for hypotenuse square requires rotation matrix
            // For simplicity in this demo, we draw it attached to the hypotenuse line
            // Re-calculating for visual correctness:
            // Length of hypotenuse = sqrt(a^2 + b^2)
            // We draw a square rotated by the angle of the hypotenuse
          />
        </g>
      )}

      {/* Correct Hypotenuse Square Implementation */}
      {showSares && (
         <g>
            <polygon
               points={`
                  ${p1.x},${p1.y}
                  ${p1.x - height * squareScale},${p1.y - width * squareScale}
                  ${p3.x - height * squareScale},${p3.y - width * squareScale}
                  ${p3.x},${p3.y}
               `}
               fill={colorC}
               fillOpacity={0.3}
               stroke={colorC}
               strokeWidth={2}
            />
         </g>
      )}

      {/* The Triangle */}
      <polygon
        points={`${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y}`}
        fill="white"
        stroke={COLORS.text}
        strokeWidth={4}
      />

      {/* Right Angle Marker */}
      <path
        d={`M ${p2.x + 20} ${p2.y} L ${p2.x + 20} ${p2.y - 20} L ${p2.x} ${p2.y - 20}`}
        stroke={COLORS.text}
        strokeWidth={2}
        fill="none"
      />

      {/* Labels */}
      {showLabels && (
        <>
          {/* Label A */}
          <text
            x={p1.x - 20}
            y={p1.y + height / 2}
            fill={colorA}
            fontSize={30}
            fontWeight="bold"
            textAnchor="end"
            dominantBaseline="middle"
            fontFamily={MATH_FONT_FAMILY}
          >
            a
          </text>
          {/* Label B */}
          <text
            x={p2.x + width / 2}
            y={p2.y + 30}
            fill={colorB}
            fontSize={30}
            fontWeight="bold"
            textAnchor="middle"
            fontFamily={MATH_FONT_FAMILY}
          >
            b
          </text>
          {/* Label C */}
          <text
            x={p1.x + width / 2 + 10}
            y={p1.y + height / 2 - 10}
            fill={colorC}
            fontSize={30}
            fontWeight="bold"
            textAnchor="middle"
            fontFamily={MATH_FONT_FAMILY}
          >
            c
          </text>
        </>
      )}
    </svg>
  );
};

