const PythagoreanTheoremVideo: React.FC = () => {
  const { durationInFrames, fps } = useVideoConfig();
  const frame = useCurrentFrame();

  // Scene Timing Calculation
  const scene1End = Math.floor(durationInFrames * 0.15);
  const scene2End = scene1End + Math.floor(durationInFrames * 0.25);
  const scene3End = scene2End + Math.floor(durationInFrames * 0.35);
  const scene4End = scene3End + Math.floor(durationInFrames * 0.15);
  // Scene 5 takes the rest

  let currentScene: React.ReactNode;
  let sceneProgress = 0;
  let frameInScene = 0;

  if (frame < scene1End) {
    // Scene 1
    frameInScene = frame;
    sceneProgress = frameInScene / (scene1End - 0);
    currentScene = <Scene1 progress={sceneProgress} frameInScene={frameInScene} />;
  } else if (frame < scene2End) {
    // Scene 2
    frameInScene = frame - scene1End;
    sceneProgress = frameInScene / (scene2End - scene1End);
    currentScene = <Scene2 progress={sceneProgress} frameInScene={frameInScene} />;
  } else if (frame < scene3End) {
    // Scene 3
    frameInScene = frame - scene2End;
    sceneProgress = frameInScene / (scene3End - scene2End);
    currentScene = <Scene3 progress={sceneProgress} frameInScene={frameInScene} />;
  } else if (frame < scene4End) {
    // Scene 4
    frameInScene = frame - scene3End;
    sceneProgress = frameInScene / (scene4End - scene3End);
    currentScene = <Scene4 progress={sceneProgress} frameInScene={frameInScene} />;
  } else {
    // Scene 5
    frameInScene = frame - scene4End;
    sceneProgress = frameInScene / (durationInFrames - scene4End);
    currentScene = <Scene5 progress={sceneProgress} frameInScene={frameInScene} />;
  }

  return <AbsoluteFill>{currentScene}</AbsoluteFill>;
};

