import React from 'react';
import { Composition, registerRoot } from 'remotion';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Sequence } from 'remotion';

// --- Types & Constants ---

type PythagoreanVideoProps = {
  title: string;
};

const COLORS = {
  background: '#F8FAFC',
  text: '#1E293B',
  primary: '#3B82F6', // Blue for 'b'
  secondary: '#10B981', // Green for 'a'
  accent: '#EF4444', // Red for 'c'
  grid: '#E2E8F0'
};

// --- Helper Components ---

const RightTriangle: React.FC<{ scale: number; showLabels: boolean }> = ({ scale, showLabels }) => {
  const size = 300;
  const half = size / 2;

  // Coordinates for a right triangle centered roughly
  // A (bottom-left), B (bottom-right), C (top-right)
  const pA = { x: -half, y: half };
  const pB = { x: half, y: half };
  const pC = { x: half, y: -half };

  return (
    <svg width={size} height={size} viewBox={-size/2 + ' ' + -size/2 + ' ' + size + ' ' + size} style={{ overflow: 'visible' }}>
      {/* Triangle */}
      <polygon
        points={`${pA.x},${pA.y} ${pB.x},${pB.y} ${pC.x},${pC.y}`}
        fill="none"
        stroke={COLORS.text}
        strokeWidth={4 * scale}
        transform={`scale(${scale})`}
      />

      {/* Right Angle Right Marker */}
      <path
        d={`M ${pB.x - 40 * scale},${pB.y} L ${pB.x - 40 * scale},${pB.y - 40 * scale} L ${pB.x},${pB.y - 40 * scale}`}
        fill="none"
        stroke={COLORS.text}
        strokeWidth={2 * scale}
        opacity={showLabels ? 1 : 0}
      />

      {/* Labels */}
      {showLabels && (
        <>
          {/* Label a (vertical) */}
          <text
            x={pC.x + 20 * scale}
            y={0}
            fill={COLORS.secondary}
            fontSize={32 * scale}
            fontWeight="bold"
            textAnchor="start"
            dominantBaseline="middle"
          >
            a
          </text>

          {/* Label b (horizontal) */}
          <text
            x={0}
            y={pB.y + 20 * scale}
            fill={COLORS.primary}
            fontSize={32 * scale}
            fontWeight="bold"
            textAnchor="middle"
            dominantBaseline="hanging"
          >
            b
          </text>

          {/* Label c (hypotenuse) */}
          <text
            x={pA.x - 20 * scale}
            y={pA.y - 20 * scale}
            fill={COLORS.accent}
            fontSize={32 * scale}
            fontWeight="bold"
            textAnchor="end"
            dominantBaseline="middle"
          >
            c
          </text>
        </>
      )}
    </svg>
  );
};

const SquareOnSide: React.FC<{ side: 'a' | 'b' | 'c'; progress: number; scale: number; label: string }> = ({ side, progress, scale, label }) => {
  const size = 300;
  const half = size / 2;
  const offset = 100 * scale; // Distance from triangle side

  let points = '';
  let color = '';
  let transformOrigin = '';

  // Define squares based on triangle vertices
  // A(-h, h), B(h, h), C(h, -h)

  if (side === 'a') {
    // Vertical side BC. Square extends to the right.
    // B(h, h) -> C(h, -h)
    // Square points: B, C, C+offset, B+offset
    const s = half * 2; // side length
    const x = half;
    const y1 = half;
    const y2 = -half;
    points = `${x},${y1} ${x + s * progress},${y1} ${x + s * progress},${y2} ${x},${y2}`;
    color = COLORS.secondary;
    transformOrigin = `${x}px ${0}px`;
  } else if (side === 'b') {
    // Horizontal side AB. Square extends downwards.
    // A(-h, h) -> B(h, h)
    const s = half * 2;
    const y = half;
    const x1 = -half;
    const x2 = half;
    points = `${x1},${y} ${x2},${y} ${x2},${y + s * progress} ${x1},${y + s * progress}`;
    color = COLORS.primary;
    transformOrigin = `0px ${y}px`;
  } else if (side === 'c') {
    // Hypotenuse AC. Square extends "outwards" (top-left).
    // A(-h, h) -> C(h, -h)
    // Vector AC = (2h, -2h). Normal (-1, -1) normalized.
    // Simplified: Just draw a square rotated 45deg relative to the diagonal, or calculate vertices.
    // Vertices of triangle: A(-h, h), C(h, -h).
    // Midpoint M = (0,0). Vector from M to A is (-h, h).
    // Rotate A around M by 90 deg CCW -> (-h, h) -> (-h, -h) ? No.
    // Let's use rotation transform for simplicity on a group.
    // The square is centered at (0,0) if we rotate it.
    // Side length = sqrt((2h)^2 + (2h)^2) = 2h * sqrt(2).
    // We want it to grow from the hypotenuse.
    color = COLORS.accent;
    transformOrigin = '0px 0px';
  }

  if (side === 'c') {
    // Special handling for Hypotenuse square using rotation
    const sideLen = half * 2 * Math.sqrt(2);
    const currentLen = sideLen * progress;

    // We draw a square centered at 0,0, then rotate it so one side aligns with AC
    // AC is at -45 degrees (or 315). 
    // To align a horizontal square side to AC, we rotate -45 deg.
    // But we want it to grow OUTWARDS. AC goes from Top-Right to Bottom-Left.
    // Outwards is Top-Left.

    return (
      <g transform={`rotate(-45)`} style={{ transformOrigin: '0px 0px' }}>
        <rect
          x={-currentLen / 2}
          y={-currentLen / 2}
          width={currentLen}
          height={currentLen}
          fill={color}
          opacity={0.6}
          stroke={color}
          strokeWidth={2 * scale}
        />
        {progress > 0.8 && (
          <text
            x={0}
            y={0}
            fill="white"
            fontSize={24 * scale}
            fontWeight="bold"
            textAnchor="middle"
            dominantBaseline="middle"
          >
            {label}
          </text>
        )}
      </g>
    );
  }

  return (
    <g>
      <polygon
        points={points}
        fill={color}
        opacity={0.6}
        stroke={color}
        strokeWidth={2 * scale}
      />
      {progress > 0.8 && (
        <text
          x={side === 'a' ? half + half : side === 'b' ? 0 : 0}
          y={side === 'a' ? 0 : half + half}
          fill="white"
          fontSize={24 * scale}
          fontWeight="bold"
          textAnchor="middle"
          dominantBaseline="middle"
        >
          {label}
        </text>
      )}
    </g>
  );
};

