const Scene3Proof: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation: Move squares a and b into c
  // 0-30: Highlight a and b
  // 30-90: Move a and b to cover c
  // 90-120: Final equation highlight

  const moveProgress = spring({ frame: frame - 30, fps, config: { damping: 30 } });

