  const scaleX = 80; // pixels per unit
  const scaleY = 80;

  // Function: f(x) = sin(x)
  const f = (x: number) => Math.sin(x);

  // Taylor Polynomials for sin(x) at a=0
  // P0(x) = 0
  // P1(x) = x
  // P2(x) = x - x^3/6 (Using 3rd order for better visual "hug" in this demo context, or sticking to quadratic logic if strictly n=2)
  // Let's stick to standard Taylor for sin(x): 0, x, x - x^3/6

  const getP = (x: number, order: number) => {
    if (order === 0) return 0;
    if (order === 1) return x;
    if (order === 2) return x - (Math.pow(x, 3) / 6);
    return x;
  };

  const generatePath = (func: (x: number) => number, color: string, dashed = false) => {
    let d = "";
    const range = 4; // -4 to 4
