      <text x={centerX + 5} y={centerY + 25} fill={COLORS.axis} fontSize={20} fontFamily={FONT_FAMILY}>0</text>

      {/* Original Function f(x) = sin(x) */}
      {generatePath(f, COLORS.primary)}

      {/* Polynomial Approximation */}
      {showPolynomial && generatePath((x) => getP(x, polynomialOrder), COLORS.accent, true)}

