const Parabola: React.FC<ParabolaProps> = ({ progress, showRoots, showAxis }) => {
  const width = 800;
  const height = 600;
  const centerX = width / 2;
  const centerY = height / 2 + 50;
  const scale = 40; // Pixels per unit

  // Parabola function: y = 0.5(x-1)^2 - 2
  // Roots at x = 1 +/- 2 = -1, 3
  const getParabolaY = (x: number) => {
    return 0.5 * Math.pow(x - 1, 2) - 2;
  };

  const generatePath = () => {
    let d = '';
    for (let px = 0; px <= width; px += 5) {
      const x = (px - centerX) / scale;
      const y = getParabolaY(x);
      const py = centerY - y * scale;
      d += `${px === 0 ? 'M' : 'L'} ${px} ${py} `;
    }
    return d;
  };

  const axisOpacity = showAxis ? interpolate(progress, [0, 0.2], [0, 1]) : 0;
  const rootsOpacity = showRoots ? interpolate(progress, [0.2, 0.5], [0, 1]) : 0;

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      {/* Grid/Axes */}
      <line
        x1={0}
        y1={centerY}
        x2={width}
        y2={centerY}
