      <line
        x1={centerX}
        y1={0}
        x2={centerX}
        y2={height}
        stroke="#ddd"
        strokeWidth={2}
        opacity={axisOpacity}
      />

      {/* Axis of Symmetry */}
      {showAxis && (
        <line
          x1={centerX + scale} // x = 1
          y1={0}
          x2={centerX + scale}
          y2={height}
          stroke={COLORS.secondary}
          strokeWidth={2}
          strokeDasharray="10,5"
          opacity={axisOpacity}
        />
      )}

      {/* Parabola */}
      <path
        d={generatePath()}
        fill="none"
        stroke={COLORS.primary}
        strokeWidth={5}
        strokeLinecap="round"
        opacity={progress}
      />

      {/* Roots */}
      {showRoots && (
        <>
          <circle
            cx={centerX - scale} // x = -1
            cy={centerY + 2 * scale} // y = 0
            r={8}
            fill={COLORS.accent}
            opacity={rootsOpacity}
          />
          <circle
            cx={centerX + 3 * scale} // x = 3
            cy={centerY + 2 * scale} // y = 0
            r={8}
            fill={COLORS.accent}
            opacity={rootsOpacity}
          />
          <text
            x={centerX - scale - 20}
            y={centerY + 2 * scale + 40}
            fontSize={24}
            fill={COLORS.text}
            opacity={rootsOpacity}
            fontFamily="sans-serif"
          >
            x₁
          </text>
          <text
            x={centerX + 3 * scale - 10}
            y={centerY + 2 * scale + 40}
            fontSize={24}
            fill={COLORS.text}
            opacity={rootsOpacity}
            fontFamily="sans-serif"
          >
            x₂
          </text>
        </>
      )}
    </svg>
  );
};

