const ParabolaGraph: React.FC<GraphProps> = ({ progress }) => {
  const width = 600;
  const height = 400;
  const centerX = width / 2;
  const centerY = height / 2 + 50;

  // Generate path for y = 0.5(x-2)^2 - 2
  const points = [];
  for (let x = -5; x <= 9; x += 0.1) {
    const y = 0.5 * Math.pow(x - 2, 2) - 2;
    const px = centerX + x * 50;
    const py = centerY - y * 50;
    points.push(`${px},${py}`);
  }

  const pathData = `M${points.join(' L')}`;

  // Roots at x = 0 and x = 4
  const root1X = centerX + 0 * 50;
  const root2X = centerX + 4 * 50;
  const rootY = centerY - 0 * 50;

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ overflow: 'visible' }}>
      {/* Axes */}
      <line x1={0} y1={centerY} x2={width} y2={centerY} stroke="#555" strokeWidth={2} />
      <line x1={centerX} y1={0} x2={centerX} y2={height} stroke="#555" strokeWidth={2} />

      {/* Parabola */}
      <path d={pathData} fill="none" stroke="#8B5CF6" strokeWidth={4} strokeOpacity={progress} />

      {/* Roots */}
      {progress > 0.5 && (
        <>
          <circle cx={root1X} cy={rootY} r={6} fill="#F59E0B" />
          <circle cx={root2X} cy={rootY} r={6} fill="#F59E0B" />
        </>
      )}
    </svg>
  );
};

