const BellCurve: React.FC<BellCurveProps> = ({
  progress,
  sigma = 1,
  showMean = false,
  showSigmaLines = false,
  shadeLevel = 0,
  opacity = 1,
}) => {
  const width = 800;
  const height = 500;
  const centerX = width / 2;
  const centerY = height - 50; // Bottom margin
  const peakY = 50; // Top margin

  // Gaussian function: y = a * exp(-(x-b)^2 / (2*c^2))
  // We map x from -4 to 4 standard deviations
  const generatePath = (sdMultiplier: number) => {
    let d = `M ${0} ${centerY} `;
    const points = 100;
    for (let i = 0; i <= points; i++) {
      const xRatio = i / points;
      const xVal = (xRatio - 0.5) * 8; // -4 to 4
      const xPx = xRatio * width;

      // Gaussian calculation
      const exponent = -0.5 * Math.pow(xVal / sigma, 2);
      const yVal = Math.exp(exponent);
      const yPx = centerY - yVal * (centerY - peakY);

      d += `L ${xPx} ${yPx} `;
    }
    d += `L ${width} ${centerY} Z`;
    return d;
  };

  const basePath = generatePath(4);

  // Generate shading paths based on standard deviations
  const getShadedPath = (limit: number) => {
    let d = `M ${centerX} ${centerY} `; // Start at center bottom

    // Right side
    const points = 50;
    for (let i = 0; i <= points; i++) {
      const xRatio = i / points;
      const xVal = xRatio * limit; // 0 to limit
      const xPx = centerX + xRatio * (width * (limit / 8));

      const exponent = -0.5 * Math.pow(xVal / sigma, 2);
      const yVal = Math.exp(exponent);
      const yPx = centerY - yVal * (centerY - peakY);

      d += `L ${xPx} ${yPx} `;
    }

    // Left side (reverse)
    for (let i = points; i >= 0; i--) {
      const xRatio = i / points;
      const xVal = xRatio * limit;
      const xPx = centerX - xRatio * (width * (limit / 8));

      const exponent = -0.5 * Math.pow(xVal / sigma, 2);
      const yVal = Math.exp(exponent);
      const yPx = centerY - yVal * (centerY - peakY);

      d += `L ${xPx} ${yPx} `;
    }

    d += "Z";
    return d;
  };

  return (
    <div
      style={{
        position: "absolute",
        left: (WIDTH - width) / 2,
        top: (HEIGHT - height) / 2 + 50,
        width,
        height,
        opacity,
      }}
    >
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        {/* Shaded Regions */}
        {shadeLevel >= 1 && (
          <path
            d={getShadedPath(1)}
            fill={COLORS.primary}
            fillOpacity={0.3}
            stroke="none"
          />
        )}
        {shadeLevel >= 2 && (
          <path
            d={getShadedPath(2)}
            fill={COLORS.secondary}
            fillOpacity={0.2}
            stroke="none"
          />
        )}
        {shadeLevel >= 3 && (
          <path
            d={getShadedPath(3)}
            fill={COLORS.accent}
            fillOpacity={0.15}
            stroke="none"
          />
        )}

        {/* Main Curve Outline */}
        <path
          d={basePath}
          fill="none"
          stroke={COLORS.text}
          strokeWidth={4}
          strokeLinecap="round"
          strokeDasharray={2000}
          strokeDashoffset={2000 * (1 - progress)}
        />

        {/* Mean Line */}
        {showMean && (
          <line
            x1={centerX}
            y1={centerY}
            x2={centerX}
            y2={peakY}
            stroke={COLORS.text}
            strokeWidth={2}
            strokeDasharray="5,5"
          />
        )}

        {/* Sigma Lines */}
        {showSigmaLines && (
          <>
            {/* -1 Sigma */}
            <line
              x1={centerX - width * (1 / 8)}
              y1={centerY}
              x2={centerX - width * (1 / 8)}
              y2={centerY - 20}
              stroke={COLORS.text}
              strokeWidth={2}
            />
            {/* +1 Sigma */}
            <line
              x1={centerX + width * (1 / 8)}
              y1={centerY}
              x2={centerX + width * (1 / 8)}
              y2={centerY - 20}
              stroke={COLORS.text}
              strokeWidth={2}
            />
            {/* -2 Sigma */}
            <line
              x1={centerX - width * (2 / 8)}
              y1={centerY}
              x2={centerX - width * (2 / 8)}
              y2={centerY - 20}
              stroke={COLORS.text}
              strokeWidth={2}
            />
            {/* +2 Sigma */}
            <line
              x1={centerX + width * (2 / 8)}
              y1={centerY}
              x2={centerX + width * (2 / 8)}
              y2={centerY - 20}
              stroke={COLORS.text}
              strokeWidth={2}
            />
             {/* -3 Sigma */}
             <line
              x1={centerX - width * (3 / 8)}
              y1={centerY}
              x2={centerX - width * (3 / 8)}
              y2={centerY - 20}
              stroke={COLORS.text}
              strokeWidth={2}
            />
            {/* +3 Sigma */}
            <line
              x1={centerX + width * (3 / 8)}
              y1={centerY}
              x2={centerX + width * (3 / 8)}
              y2={centerY - 20}
              stroke={COLORS.text}
              strokeWidth={2}
            />
