const BellCurve: React.FC<{ 
  mean: number; 
  stdDev: number; 
  color?: string; 
  fillOpacity?: number;
  highlightRange?: [number, number];
  highlightColor?: string;
}> = ({ mean, stdDev, color = COLORS.primary, fillOpacity = 0.2, highlightRange, highlightColor = COLORS.secondary }) => {
  const width = 800;
  const height = 400;
  const centerY = 350;
  const centerX = 400;

  // Gaussian function
  const gaussian = (x: number) => {
    const exponent = -0.5 * Math.pow((x - mean) / stdDev, 2);
    return Math.exp(exponent);
  };

  // Generate path data
  const generatePath = (startX: number, endX: number, close: boolean) => {
    let d = `M ${startX} ${centerY}`;
    const step = 2;
    for (let x = startX; x <= endX; x += step) {
      const y = centerY - (gaussian(x) * 300);
      d += ` L ${x} ${y}`;
    }
    if (close) {
      d += ` L ${endX} ${centerY} Z`;
    }
    return d;
  };

  // Map visual x to logical x
  const mapX = (visualX: number) => mean + (visualX - centerX) * (stdDev / 100);

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ overflow: 'visible' }}>
      {/* Grid lines */}
      <line x1={0} y1={centerY} x2={width} y2={centerY} stroke={COLORS.grid} strokeWidth={2} />

      {/* Highlight Region (if any) */}
      {highlightRange && (
        <path
          d={generatePath(
            centerX + (highlightRange[0] - mean) * (100 / stdDev),
            centerX + (highlightRange[1] - mean) * (100 / stdDev),
            true
          )}
          fill={highlightColor}
          opacity={0.5}
        />
      )}

      {/* Main Curve */}
      <path
        d={generatePath(0, width, false)}
        stroke={color}
        strokeWidth={4}
        fill="none"
      />

      {/* Mean Line */}
      <line x1={centerX} y1={centerY} x2={centerX} y2={centerY - 300} stroke={COLORS.text} strokeWidth={2} strokeDasharray="5,5" />
    </svg>
  );
};

