const GridSystem: React.FC<{
  transformProgress: number;
  showEigenvectors: boolean;
  showDiagonalBasis: boolean;
}> = ({ transformProgress, showEigenvectors, showDiagonalBasis }) => {
  const size = 400;
  const center = size / 2;
  const step = 40;

  // Transformation Matrix A
  // Let's use a shear + scale matrix for interesting visuals
  // A = [[2, 1], [0, 1]]
  // Eigenvectors: v1 = [1, 0] (lambda = 2), v2 = [-1, 1] (lambda = 1)
  const applyTransform = (x: number, y: number, t: number) => {
    // Linear interpolation between Identity and A
    // I = [[1, 0], [0, 1]]
    // A = [[2, 1], [0, 1]]

    const m00 = 1 + (2 - 1) * t;
    const m01 = 0 + (1 - 0) * t;
    const m10 = 0;
    const m11 = 1; // Stays 1

    const nx = m00 * x + m01 * y;
    const ny = m10 * x + m11 * y;
    return { x: nx, y: ny };
  };

  // Helper to map grid coordinates to SVG coordinates
  const toSvg = (x: number, y: number) => {
    return `${center + x},${center - y}`;
  };

  const lines: React.ReactNode[] = [];

  // Draw Grid
  for (let i = -5; i <= 5; i++) {
    const val = i * step;

    // Vertical lines
    let vPath = `M ${toSvg(val, -5 * step)}`;
    for (let j = -5; j <= 5; j++) {
      const p = applyTransform(val, j * step, transformProgress);
      vPath += ` L ${toSvg(p.x, p.y)}`;
    }
    lines.push(
      <path
        key={`v-${i}`}
        d={vPath}
        stroke={COLORS.grid}
        strokeWidth="2"
        fill="none"
      />
    );

    // Horizontal lines
    let hPath = `M ${toSvg(-5 * step, val)}`;
    for (let j = -5; j <= 5; j++) {
      const p = applyTransform(j * step, val, transformProgress);
      hPath += ` L ${toSvg(p.x, p.y)}`;
    }
    lines.push(
      <path
        key={`h-${i}`}
        d={hPath}
        stroke={COLORS.grid}
        strokeWidth="2"
        fill="none"
      />
    );
  }

  // Eigenvector 1: [1, 0] (Blue) - Stays on X axis
  const ev1Start = applyTransform(-2 * step, 0, transformProgress);
  const ev1End = applyTransform(2 * step, 0, transformProgress);

  // Eigenvector 2: [-1, 1] (Red) - Slope -1
  const ev2Start = applyTransform(2 * step, -2 * step, transformProgress);
  const ev2End = applyTransform(-2 * step, 2 * step, transformProgress);

  // Diagonal Basis Vectors (Visual representation of P)
  // These are the eigenvectors normalized and scaled for display
  const db1Start = applyTransform(0, 0, transformProgress);
  const db1End = applyTransform(1.5 * step, 0, transformProgress); // v1

  const db2Start = applyTransform(0, 0, transformProgress);
  const db2End = applyTransform(-1.5 * step, 1.5 * step, transformProgress); // v2

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      {/* Background */}
      <rect width={size} height={size} fill={COLORS.background} />

      {/* Grid Lines */}
      {lines}

      {/* Standard Axes */}
      <line
        x1={0} y1={center} x2={size} y2={center}
        stroke={COLORS.axis} strokeWidth="2"
      />
      <line
        x1={center} y1={0} x2={center} y2={size}
        stroke={COLORS.axis} strokeWidth="2"
      />

      {/* Eigenvectors */}
      {showEigenvectors && (
        <g opacity={showDiagonalBasis ? 0.3 : 1}>
          <line
            x1={center + ev1Start.x} y1={center - ev1Start.y}
            x2={center + ev1End.x} y2={center - ev1End.y}
            stroke={COLORS.primary} strokeWidth="6"
            markerEnd="url(#arrowhead-blue)"
          />
          <line
            x1={center + ev2Start.x} y1={center - ev2Start.y}
            x2={center + ev2End.x} y2={center - ev2End.y}
            stroke={COLORS.secondary} strokeWidth="6"
            markerEnd="url(#arrowhead-red)"
          />
        </g>
      )}

      {/* Diagonal Basis Highlight (Scene 4) */}
      {showDiagonalBasis && (
        <g>
          <line
            x1={center + db1Start.x} y1={center - db1Start.y}
            x2={center + db1End.x} y2={center - db1End.y}
            stroke={COLORS.primary} strokeWidth="8"
          />
          <line
            x1={center + db2Start.x} y1={center - db2Start.y}
            x2={center + db2End.x} y2={center - db2End.y}
            stroke={COLORS.secondary} strokeWidth="8"
          />
          {/* New Axis Labels */}
          <text x={center + db1End.x + 10} y={center - db1End.y} fill={COLORS.primary} fontSize="20" fontWeight="bold">e1</text>
          <text x={center + db2End.x - 10} y={center - db2End.y - 10} fill={COLORS.secondary} fontSize="20" fontWeight="bold">e2</text>
        </g>
      )}

      {/* Arrow Definitions */}
      <defs>
        <marker id="arrowhead-blue" markerWidth="10" markerHeight="7" refX="9" refY="3.5" orient="auto">
          <polygon points="0 0, 10 3.5, 0 7" fill={COLORS.primary} />
        </marker>
        <marker id="arrowhead-red" markerWidth="10" markerHeight="7" refX="9" refY="3.5" orient="auto">
          <polygon points="0 0, 10 3.5, 0 7" fill={COLORS.secondary} />
        </marker>
      </defs>
    </svg>
  );
};

