import React from 'react';
import { Composition, registerRoot } from 'remotion';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Sequence } from 'remotion';

// --- Types & Constants ---

type VectorProps = {
  x: number;
  y: number;
  color: string;
  label?: string;
  scale?: number;
};

type MatrixProps = {
  values: number[][];
  label?: string;
};

const COLORS = {
  background: '#0f172a',
  text: '#f8fafc',
  primary: '#8B5CF6', // Violet
  secondary: '#ECFF99', // Light Green
  accent: '#3B82F6', // Blue
  grid: '#334155',
  vector: '#ffffff',
  eigen: '#EC4899', // Pink
};

// --- Helper Components ---

const Title: React.FC<{ title: string; subtitle: string }> = ({ title, subtitle }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const opacity = spring({ frame, fps, config: { damping: 200 } });
  const slideUp = interpolate(spring({ frame, fps, config: { damping: 25 } }), [0, 1], [50, 0]);

  return (
    <div style={{ 
      position: 'absolute', 
      top: '15%', 
      left: 0, 
      right: 0, 
      textAlign: 'center',
      transform: `translateY(${slideUp}px)`,
      opacity
    }}>
      <h1 style={{ 
        fontSize: 80, 
        fontWeight: 'bold', 
        color: COLORS.text, 
        margin: 0,
        fontFamily: 'sans-serif'
      }}>
        {title}
      </h1>
      <h2 style={{ 
        fontSize: 40, 
        color: COLORS.primary, 
        marginTop: 20,
        fontFamily: 'sans-serif'
      }}>
        {subtitle}
      </h2>
    </div>
  );
};

const MatrixDisplay: React.FC<MatrixProps> = ({ values, label }) => {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
      {label && <span style={{ color: COLORS.text, fontSize: 24 }}>{label}</span>}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: `repeat(${values[0].length}, 1fr)`, 
        gap: 10, 
        padding: 20, 
        border: `2px solid ${COLORS.primary}`, 
