// --- Visualization Components ---

const VectorSpace: React.FC<{ progress: number; showEigens: boolean }> = ({ progress, showEigens }) => {
  const size = 400;
  const center = size / 2;
  const scale = 80; // pixels per unit

  // Transformation Matrix: [[2, 1], [1, 2]]
  // Eigenvalues: 3 (vector [1,1]), 1 (vector [-1,1])
  const transform = (x: number, y: number) => {
    const t = progress; // 0 to 1
    const nx = x * (1 + t) + y * t;     // Linear interp to 2x + y
    const ny = x * t + y * (1 + t);     // Linear interp to x + 2y
    return { x: nx, y: ny };
  };

  const toScreen = (x: number, y: number) => ({
    x: center + x * scale,
    y: center - y * scale
  });

  return (
    <div style={{ position: 'relative', width: size, height: size }}>
      <svg width={size} height={size} style={{ overflow: 'visible' }}>
        {/* Grid */}
        {[...Array(5)].map((_, i) => {
          const offset = (i - 2) * scale;
          return (
            <g key={i}>
              <line x1={offset} y1={0} x2={offset} y2={size} stroke={COLORS.grid} strokeWidth={1} />
              <line x1={0} y1={offset} x2={size} y2={offset} stroke={COLORS.grid} strokeWidth={1} />
            </g>
          );
        })}

        {/* Axes */}
        <line x1={0} y1={center} x2={size} y2={center} stroke={COLORS.text} strokeWidth={2} />
        <line x1={center} y1={0} x2={center} y2={size} stroke={COLORS.text} strokeWidth={2} />

        {/* Standard Basis Vectors (Transforming) */}
        {[
          { x: 1, y: 0, color: COLORS.accent, label: 'i' },
          { x: 0, y: 1, color: COLORS.accent, label: 'j' }
        ].map((v, idx) => {
          const current = transform(v.x, v.y);
          const start = toScreen(0, 0);
          const end = toScreen(current.x, current.y);

          return (
            <g key={idx}>
              <line x1={start.x} y1={start.y} x2={end.x} y2={end.y} stroke={v.color} strokeWidth={4} markerEnd="url(#arrow)" />
              <text x={end.x + 10} y={end.y} fill={v.color} fontSize={20}>{v.label}</text>
            </g>
          );
        })}

        {/* Eigenvectors (Invariant Lines) */}
        {showEigens && [
          { x: 1, y: 1, val: 3 },   // Eigenvalue 3
          { x: -1, y: 1, val: 1 }   // Eigenvalue 1
        ].map((v, idx) => {
          const current = transform(v.x, v.y);
          const start = toScreen(0, 0);
          const end = toScreen(current.x, current.y);

          return (
            <g key={`eigen-${idx}`}>
              <line x1={start.x} y1={start.y} x2={end.x} y2={end.y} stroke={COLORS.eigen} strokeWidth={6} />
              <circle cx={end.x} cy={end.y} r={6} fill={COLORS.eigen} />
              <text x={end.x + 15} y={end.y} fill={COLORS.eigen} fontSize={24} fontWeight="bold">λ={v.val}</text>
            </g>
          );
        })}

        <defs>
          <marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto" markerUnits="strokeWidth">
            <path d="M0,0 L0,6 L9,3 z" fill={COLORS.accent} />
          </marker>
        </defs>
      </svg>
    </div>
  );
};

